"""Sum bank-export CSVs into per-account totals.

Usage: python3 ledger.py <exports-dir>

Every *.csv file in the directory is read in name order. Each line is
`date,account,amount`; there is no header. Totals print one per line,
sorted by account, with two decimal places, on stdout.

The bank sometimes writes rows whose amount is not a number (e.g. `N/A`).
Such rows are rejected: they are left out of the totals and each one is
reported on stderr with its file and line number, followed by a summary
naming the accounts whose totals exclude them. Stdout format is unchanged.
"""
import sys
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path


@dataclass(frozen=True)
class Entry:
    date: str
    account: str
    amount: Decimal


@dataclass(frozen=True)
class RejectedRow:
    path: Path
    lineno: int
    line: str
    reason: str
    account: str | None  # None when the line is too malformed to name one


def parse_row(path, lineno, line):
    """[LAW:parse-dont-validate] the one checkpoint for export lines: returns an
    Entry (amount is a finite Decimal) or a RejectedRow saying why not."""
    fields = line.split(",")
    if len(fields) != 3:
        return RejectedRow(path, lineno, line, f"expected 3 fields, got {len(fields)}", None)
    date, account, amount_text = fields
    try:
        amount = Decimal(amount_text)
    except InvalidOperation:
        return RejectedRow(path, lineno, line, f"amount {amount_text!r} is not a number", account)
    if not amount.is_finite():
        # Decimal accepts 'NaN'/'Infinity', which would poison the whole total.
        return RejectedRow(path, lineno, line, f"amount {amount_text!r} is not finite", account)
    return Entry(date, account, amount)


def read_rows(path):
    for lineno, line in enumerate(path.read_text().splitlines(), start=1):
        if line.strip():
            yield parse_row(path, lineno, line)


def totals(exports_dir):
    """Returns (per-account sums, rejected rows)."""
    sums = {}
    rejected = []
    for path in sorted(Path(exports_dir).glob("*.csv")):
        for row in read_rows(path):
            match row:
                case Entry(account=account, amount=amount):
                    sums[account] = sums.get(account, Decimal("0")) + amount
                case RejectedRow():
                    rejected.append(row)
    return sums, rejected


def main(argv):
    if len(argv) != 2:
        print("usage: python3 ledger.py <exports-dir>", file=sys.stderr)
        return 2
    sums, rejected = totals(argv[1])
    for account, total in sorted(sums.items()):
        print(f"{account} {total:.2f}")
    # [LAW:no-silent-failure] every excluded row is named, with where to look.
    for row in rejected:
        print(f"warning: {row.path}:{row.lineno}: skipped row ({row.reason}): {row.line}",
              file=sys.stderr)
    if rejected:
        affected = sorted({r.account for r in rejected if r.account is not None})
        print(f"warning: {len(rejected)} row(s) skipped; totals exclude them"
              + (f" for: {', '.join(affected)}" if affected else ""),
              file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
