python3 ledger.py exports; echo "exit=$?"
echo "--- stdout only:"; python3 ledger.py exports 2>/dev/null
d=$(mktemp -d); printf '2026-10-01,x,NaN\n2026-10-02,x,5\nbroken line\n' > $d/a.csv; python3 ledger.py $d; rm -r $d

